function saveValue(k,v){state[k]=v;updateSummary()}
function field(k,label,type='text',hint=''){const id='rich-'+k;return `<div class="field ${type==='textarea'?'full':''}"><label for="${id}">${esc(label)}</label>${type==='textarea'?`<textarea id="${id}" oninput="saveValue('${k}',this.value)">${esc(state[k]||'')}</textarea>`:`<input id="${id}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(state[k]??'')}" oninput="saveValue('${k}',this.value)">`}${hint?`<span class="helper">${esc(hint)}</span>`:''}</div>`}
function selectField(k,label,options){return `<div class="field"><label for="rich-${k}">${esc(label)}</label><select id="rich-${k}" onchange="saveValue('${k}',this.value)">${options.map(t=>`<option ${state[k]===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function toggleField(k,label,callback='render()'){return `<label class="quiet-check"><input type="checkbox" ${state[k]?'checked':''} onchange="state['${k}']=this.checked;${callback}">${label}</label>`}
function fold(title,body,open=false){return `<details class="fold" ${open?'open':''}><summary>${title}</summary>${body}</details>`}
function sourceLink(book,range){return `<button type="button" class="link" onclick="showSources(${book})">${esc(sourceBooks[book].name)} · Sheet1!${range}</button>`}
function viewValues(items){return `<div class="data-list">${items.map(([label,value])=>`<div class="summary-line"><span>${esc(label)}</span><b>${esc(value!==''&&value!=null?value:'ยังไม่ระบุ')}</b></div>`).join('')}</div>`}
function writeLocal(message='เก็บค่าในตัวอย่างแล้ว · รีโหลดจะกลับค่าเริ่มต้น'){toast(message)}
function setSecondary(value){secondary=value;activeTab='ส่วนอื่น';render()}
function costTotal(){let total=0,missing=false;costs.forEach(c=>{if(c.quantity===''||c.rate===''){missing=true;return}total+=Number(c.quantity)*Number(c.rate)});return !costs.some(c=>c.rate!=='')?'ยังไม่ได้ประมาณการ':`${total.toLocaleString('th-TH')} บาท${missing?' · ยังไม่ครบทุกอัตรา':''}`}
function costsForm(){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>รายการ</th><th>จำนวน</th><th>อัตรา / บาท</th><th></th></tr></thead><tbody>${costs.map((c,i)=>`<tr><td><input aria-label="รายการค่าใช้จ่าย ${i+1}" value="${esc(c.label)}" oninput="costs[${i}].label=this.value"></td><td><input type="number" min="0" aria-label="จำนวน ${i+1}" value="${c.quantity}" oninput="costs[${i}].quantity=this.value;refreshCosts()"></td><td><input type="number" min="0" step="0.01" aria-label="อัตรา ${i+1}" value="${c.rate}" oninput="costs[${i}].rate=this.value;refreshCosts()"></td><td><button type="button" class="link" onclick="costs.splice(${i},1);render()">ลบ</button></td></tr>`).join('')}</tbody></table></div><div class="row between"><button type="button" class="link" onclick="costs.push({label:'',quantity:'1',rate:''});render()">+ เพิ่มรายการค่าใช้จ่าย</button><span id="cost-total" class="estimate-total">${costTotal()}</span></div>`}
function refreshCosts(){const e=document.getElementById('cost-total');if(e)e.textContent=costTotal()}
function repeatRows(kind,arr){return arr.map((r,i)=>`<div class="record-row"><button type="button" class="remove" onclick="${kind}.splice(${i},1);render()">ลบรายที่ ${i+2}</button><h3>${kind==='extraCustomers'?'ผู้มอบหมาย':'ลูกความ'}รายที่ ${i+2}</h3><div class="fields ${kind==='extraCustomers'?'payer-fields':''}"><div class="field"><label for="${kind}-${i}-name">ชื่อ / เลือกจากทะเบียน</label><input id="${kind}-${i}-name" value="${esc(r.name||'')}" oninput="${kind}[${i}].name=this.value"></div>${kind==='extraCustomers'?`<div class="field"><label for="${kind}-${i}-share">สัดส่วนที่จ่าย (%)</label><input id="${kind}-${i}-share" type="number" min="0" max="100" value="${esc(r.share||'')}" oninput="${kind}[${i}].share=this.value"></div><div class="field full"><label for="${kind}-${i}-contact">ผู้ติดต่อ</label><input id="${kind}-${i}-contact" value="${esc(r.contact||'')}" oninput="${kind}[${i}].contact=this.value"></div>`:''}</div></div>`).join('')}
function peopleForm(){return `<div class="fields payer-fields">${field('customer','ผู้มอบหมายงาน / ผู้จ่ายเงิน')}${field('contact','ผู้ติดต่อของผู้มอบหมายรายที่ 1')}${field('customerShare','สัดส่วนที่จ่ายรายที่ 1 (%)','number')}</div>${repeatRows('extraCustomers',extraCustomers)}<div class="extra-actions"><button type="button" class="link" onclick="extraCustomers.push({name:'',contact:'',share:''});render()">+ เพิ่มผู้มอบหมาย / ผู้จ่าย</button><button type="button" class="link" onclick="registryDialog()">+ สร้างทะเบียนลูกค้า</button></div><hr class="section-separator">${toggleField('same','ลูกความคนเดียวกับผู้มอบหมายรายที่ 1',"if(state.same)state.client=state.customer;render()")}${field('client','ลูกความหลัก / เลือกจากทะเบียนหรือพิมพ์ชื่อใหม่')}${toggleField('unknownClient','ยังไม่ทราบชื่อลูกความ ระบุภายหลัง')}${selectField('clientType','ประเภทลูกความใหม่',['นิติบุคคล','บุคคลธรรมดา'])}${repeatRows('extraClients',extraClients)}<button type="button" class="link" style="margin-top:14px" onclick="extraClients.push({name:''});render()">+ เพิ่มลูกความอีกราย</button>`}
function teamForm(){return `<div class="fields">${selectField('lawyer','ทนายผู้รับผิดชอบหลัก',['อรณิชา วัฒนกุล','ธนกร เจริญกิจ','ณัฐชา ศิริกุล'])}<div class="helper">ภาระงานตัวอย่าง<br>อรณิชา: หลัก 5 · ผู้ช่วย 1 · ใกล้กำหนด 2<br>ธนกร: หลัก 3 · ผู้ช่วย 2 · ใกล้กำหนด 1<br>ณัฐชา: หลัก 2 · ผู้ช่วย 1 · ใกล้กำหนด 0</div></div><p class="small" style="margin-top:18px">ทนายผู้ช่วย — เลือกได้หลายคน</p>${['ธนกร เจริญกิจ','ณัฐชา ศิริกุล'].map(t=>`<label class="quiet-check"><input type="checkbox" ${buddies.includes(t)?'checked':''} onchange="if(this.checked)buddies.push('${t}');else buddies.splice(buddies.indexOf('${t}'),1)">${t}</label>`).join('')}`}
function courtForm(){return `<div class="fields">${selectField('courtLevel','ระดับศาล',['ศาลชั้นต้น','ศาลอุทธรณ์','ศาลฎีกา'])}${field('court','ศาล / ค้นหาหรือระบุภายหลัง')}${field('number','เลขคดีดำ')}${field('redNumber','เลขคดีแดง')}${selectField('partyRole','ฝ่ายเรา',['ยังไม่ระบุ','โจทก์','จำเลย'])}</div>`}
function appointmentForm(){return `${toggleField('initialActivity','เพิ่มนัดหมายแรกพร้อมสร้างคดี')}${state.initialActivity?`<div class="fields">${field('activityTitle','หัวข้อนัดหมาย')}${selectField('activityType','ประเภทนัดหมาย',['นัดศาล','นัดลูกค้า','ยื่นคำร้อง','กำหนดส่ง','อื่น ๆ'])}${field('activityAt','วันที่และเวลา','datetime-local')}${field('activityDescription','รายละเอียดนัดหมาย','textarea')}</div>`:'<p class="helper">เพิ่มภายหลังได้ในไทม์ไลน์คดี</p>'}`}
function customForm(){return `<p class="section-caption">รองรับฟิลด์ตามประเภทคดีเดิม (ข้อความ ตัวเลข วันที่ และตัวเลือก) ไม่จำกัดเฉพาะตัวอย่างขนส่ง</p>${customItems.map((r,i)=>`<div class="record-row fields"><div class="field"><label>ชื่อฟิลด์</label><input aria-label="ชื่อฟิลด์เพิ่มเติม ${i+1}" value="${esc(r.label)}" oninput="customItems[${i}].label=this.value"></div><div class="field"><label>ค่า</label><input aria-label="ค่าฟิลด์เพิ่มเติม ${i+1}" value="${esc(r.value)}" oninput="customItems[${i}].value=this.value"></div></div>`).join('')}<button type="button" class="link" onclick="customItems.push({label:'',value:''});render()">+ เพิ่มฟิลด์ตามประเภทคดี</button>`}
function filePicker(){return `<div class="field"><label for="file-picker">แนบเอกสาร (เลือกได้หลายไฟล์)</label><input id="file-picker" type="file" multiple onchange="Array.from(this.files).forEach(f=>uploadedFiles.push({name:f.name,size:f.size,category:'ยังไม่จัดหมวด',version:'1',status:'รอตรวจ'}));render()"><p class="helper">ตัวอย่างเก็บเฉพาะชื่อและขนาดไฟล์ในหน้านี้ ไม่มีการอัปโหลด</p></div>${uploadedFiles.map(f=>`<div class="summary-line"><span>${esc(f.name)}</span><b>${Math.ceil(f.size/1024)} KB · ${f.status}</b></div>`).join('')}`}
function aiUpload(){return `${filePicker()}<p class="data-note">พื้นที่ข้อเสนอจากเอกสาร: ชื่อคดี ศาล ทุนทรัพย์ และสรุปข้อเท็จจริง พร้อมเอกสารต้นทางและการยืนยันรายฟิลด์</p><button type="button" class="btn" onclick="showSuggestion()">ดูตัวอย่างข้อเสนอจากเอกสาร</button>`}
function cargoData(){return `<p class="data-note">${sourceLink(2,'B2:B19')} · 17 หัวข้อต้นฉบับ โดยแยก Policy No. และ Claim No. เป็นคนละช่อง</p><div class="fields">${cargoFields.map(([key,label,cell,type])=>field(key,label,type||'text',`Sheet1!${cell}`)).join('')}${field('weightUnit','หน่วยน้ำหนัก')}${field('claimCurrency','สกุลเงินของยอดเรียกร้อง')}${field('timeBarStart','วันเริ่มนับอายุความ','date')}${field('timeBarConfirmed','วันครบกำหนดที่ทนายยืนยัน','date')}${field('timeBarBasis','หลักฐานและเหตุผลการนับอายุความ','textarea')}</div><p class="data-note">Law / Limitation / Time bar / Opinion เป็นข้อมูลการพิจารณาที่ยังกรอกได้ ไม่ถือว่ามีข้อสรุปจากการเลือกประเภทขนส่ง</p>`}
function considerationPanel(){return `<div class="block-title"><h2>ประเด็นพิจารณา Cargo claim</h2><span class="pill">12 แถว</span></div><p class="data-note">${sourceLink(0,'A4:C15')} · เก็บเลขข้อเดิม รวมข้อ 6 ที่ซ้ำกันสองแถว</p>${considerations.map((c,i)=>`<section class="cargo-review-row"><div class="row between"><h3>${c.no}. ${esc(c.label)}</h3><span class="source-ref">B${c.sourceRow}:C${c.sourceRow}</span></div><p class="muted small">${esc(c.original)}</p>${c.hint?`<div class="source-hint">ตัวเลือก / หมายเหตุในต้นฉบับ: ${esc(c.hint)}</div>`:''}<div class="fields"><div class="field"><label for="consider-${i}-status">สถานะการพิจารณา</label><select id="consider-${i}-status" onchange="considerations[${i}].status=this.value">${['ยังไม่ตรวจ','กำลังตรวจ','ตรวจแล้ว'].map(t=>`<option ${t===c.status?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="consider-${i}-evidence">เอกสาร / หน้าอ้างอิง</label><input id="consider-${i}-evidence" value="${esc(c.evidence)}" oninput="considerations[${i}].evidence=this.value"></div><div class="field full"><label for="consider-${i}-answer">ผลพิจารณา</label><textarea id="consider-${i}-answer" oninput="considerations[${i}].answer=this.value">${esc(c.answer)}</textarea></div><div class="field full"><label for="consider-${i}-note">หมายเหตุของผู้พิจารณา</label><input id="consider-${i}-note" value="${esc(c.note)}" oninput="considerations[${i}].note=this.value"></div></div></section>`).join('')}<button class="btn primary" style="margin-top:20px" onclick="writeLocal()">เก็บผลพิจารณาในตัวอย่าง</button>`}
function cargoDocsPanel(){return `<div class="block-title"><h2>เอกสารประกอบ Cargo claim</h2><span class="pill">16 รายการ</span></div><p class="data-note">${sourceLink(1,'A5:E20')} · สถานะต้นฉบับเป็น Yes / No และมี Remark; สถานะว่างแสดงเป็น “ยังไม่ตรวจ”</p><p class="document-status" id="doc-summary">มีเอกสาร ${claimDocs.filter(d=>d.status==='Yes').length}/16 · ยังไม่ตรวจ ${claimDocs.filter(d=>d.status==='ยังไม่ตรวจ').length}</p>${claimDocs.map((d,i)=>`<section class="cargo-doc"><h3>${d.no}. ${esc(d.label)}</h3><span class="source-ref">Sheet1!B${d.sourceRow}:E${d.sourceRow}</span><div class="fields"><div class="field"><label for="doc-${i}-status">สถานะเอกสาร</label><select id="doc-${i}-status" onchange="claimDocs[${i}].status=this.value;document.getElementById('doc-summary').textContent='มีเอกสาร '+claimDocs.filter(d=>d.status==='Yes').length+'/16 · ยังไม่ตรวจ '+claimDocs.filter(d=>d.status==='ยังไม่ตรวจ').length">${['ยังไม่ตรวจ','Yes','No'].map(t=>`<option ${d.status===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="doc-${i}-file">ไฟล์ / เลขอ้างอิงเอกสาร</label><input id="doc-${i}-file" value="${esc(d.file)}" oninput="claimDocs[${i}].file=this.value"></div><div class="field full"><label for="doc-${i}-remark">Remark / หมายเหตุ${i===15?' — ระบุเอกสารอื่นเพิ่มเติม':''}</label><textarea id="doc-${i}-remark" oninput="claimDocs[${i}].remark=this.value">${esc(d.remark)}</textarea></div><div class="field full"><label for="doc-${i}-review">ผลตรวจเนื้อหา (แยกจากการมีไฟล์)</label><select id="doc-${i}-review" onchange="claimDocs[${i}].review=this.value">${['ยังไม่ตรวจเนื้อหา','ต้องขอเพิ่ม / แก้ไข','ตรวจเนื้อหาแล้ว'].map(t=>`<option ${d.review===t?'selected':''}>${t}</option>`).join('')}</select></div></div></section>`).join('')}`}
createPage=function(){const sections=[
 ['case-basic','ข้อมูลคดีและเลขอ้างอิง',`<div class="fields"><div class="field full"><label for="rich-type">ประเภทคดี</label><select id="rich-type" onchange="state.type=this.value;render()">${['Corporate','Criminal','Family Law','Intellectual Property','Litigation','การแพทย์','ขนส่ง / Cargo claim'].map(t=>`<option ${state.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="full">${field('title','ชื่อคดี *')}</div><div class="full">${toggleField('autoTitle','เติมชื่อจากประเภทคดีและลูกความ',"if(state.autoTitle)state.title=state.type+' — '+state.client;render()")}</div>${field('customerRef','เลขอ้างอิงลูกค้า')}${selectField('playbook','Playbook / วิธีทำงาน',['ยังไม่เลือก','Corporate · v1','Criminal · v1','คดีทางการแพทย์ · v1','Cargo checklist · ตัวอย่างจาก Excel'])}<p class="helper full">เลขอ้างอิงสำนักงาน / เลขแฟ้มสร้างอัตโนมัติเมื่อเปิดคดีจริง · ตัวอย่างนี้ยังไม่จองหมายเลข</p></div>${fold('ข้อมูลศาลและหมายเลขคดี',courtForm())}${fold('รายละเอียดและฟิลด์เฉพาะประเภทคดี',field('description','รายละเอียดคดี','textarea')+customForm())}`],
 ['case-people','ลูกค้า ลูกความ และทีม',peopleForm()+fold('ผู้รับผิดชอบหลักและทนายผู้ช่วย',teamForm(),true)],
 ['case-extra','การเงิน นัดหมาย และเอกสาร',fold('ทุนทรัพย์ รายได้ และประมาณการค่าใช้จ่าย',`<div class="fields">${field('amount','ทุนทรัพย์ (บาท)','number')}${field('estimatedFee','รายได้โดยประมาณ (บาท)','number')}</div>${costsForm()}`)+fold('นัดหมายแรก',appointmentForm())+fold('เอกสารแนบและข้อเสนอจาก AI',aiUpload())+(state.type==='ขนส่ง / Cargo claim'?fold('Cargo claim · ข้อมูลเคลมจากตารางตัวอย่าง',cargoData())+fold('Cargo claim · ประเด็นพิจารณา 12 แถว',considerationPanel())+fold('Cargo claim · เช็กลิสต์เอกสาร 16 รายการ',cargoDocsPanel()):'')]
 ];return `<div class="page-heading row between"><div><div class="eyebrow">NEW MATTER</div><h1>เริ่มต้นคดีใหม่</h1><p class="muted small">ข้อมูลหลักอยู่ด้านหน้า รายละเอียดทุกกลุ่มเปิดกรอกเพิ่มได้</p></div><button class="btn" onclick="setPage('detail')">ดูหน้าคดี</button></div><p class="data-note">Mockup ฉบับรักษาข้อมูลเดิม + โครง Cargo claim จากเอกสารตัวอย่าง · <a href="coverage.md" target="_blank">ดูรายการเทียบข้อมูล</a></p><div class="focus-steps">${sections.map((s,i)=>`<button type="button" class="${step===i?'active':''}" onclick="step=${i};render()">${i+1} &nbsp; ${s[1]}</button>`).join('')}</div><div class="new-layout"><nav class="ledger-nav">${sections.map(s=>`<a href="#${s[0]}">${s[1]}</a>`).join('')}</nav><form class="paper" onsubmit="event.preventDefault();nextCreate()">${sections.map((s,i)=>`<section id="${s[0]}" class="form-section ${step===i?'focus-current':''}"><div class="section-head"><span class="section-num">0${i+1}</span><div><h2>${s[1]}</h2></div></div>${s[2]}</section>`).join('')}<footer class="form-footer"><span class="helper">ค่าที่กรอกอยู่ในตัวอย่างเท่านั้น</span><div class="row"><button type="button" class="link" onclick="${variant==='B'&&step>0?'step--;render()':"setPage('detail')"}">${variant==='B'&&step>0?'ย้อนกลับ':'กลับหน้าคดี'}</button><button type="submit" class="btn primary">${variant==='B'&&step<2?'ถัดไป':'ตรวจสอบและสร้างคดี'} ${icon('arrow')}</button></div></footer></form><aside class="summary-side"><h2>ข้อมูลในแฟ้มนี้</h2><div class="docket"><div class="ref">NEW MATTER</div><h3 data-value="title">${esc(state.title)}</h3><span class="pill">${state.type}</span></div>${sections.map(s=>`<a class="side-jump" href="#${s[0]}">${s[1]} ↗</a>`).join('')}<div class="summary-line"><span>ผู้มอบหมาย</span><b>${1+extraCustomers.length} ราย</b></div><div class="summary-line"><span>ลูกความ</span><b>${1+extraClients.length} ราย</b></div><div class="summary-line"><span>ค่าใช้จ่าย</span><b>${costTotal()}</b></div><p class="note">${icon('info')}<span>การเปิดคดีไม่เท่ากับยื่นฟ้อง<br>เพิ่มศาลและวันนัดเมื่อทราบข้อมูล</span></p><button class="link" onclick="showSources(0)">เปิดเอกสารตัวอย่างทั้ง 3 ไฟล์</button></aside></div>`};
showReview=function(){const groups=[['ข้อมูลคดี',[['ชื่อคดี',state.title],['ประเภท',state.type],['Playbook',state.playbook],['เลขอ้างอิงลูกค้า',state.customerRef],['เลขอ้างอิงสำนักงาน / แฟ้ม','สร้างอัตโนมัติในระบบจริง'],['ศาล',state.court],['ระดับศาล',state.courtLevel],['เลขดำ',state.number],['เลขแดง',state.redNumber],['ฝ่ายเรา',state.partyRole],['รายละเอียด',state.description],...customItems.map(r=>[r.label,r.value])]],['คู่เกี่ยวข้อง',[['ผู้มอบหมายหลัก',state.customer],['ผู้ติดต่อ',state.contact],['สัดส่วนผู้จ่ายหลัก',state.customerShare],...extraCustomers.flatMap((r,i)=>[[`ผู้มอบหมาย ${i+2}`,r.name],[`ผู้ติดต่อ ${i+2}`,r.contact],[`สัดส่วน ${i+2}`,r.share]]),['ลูกความหลัก',state.unknownClient?'ยังไม่ทราบชื่อ':state.client],['ประเภทลูกความใหม่',state.clientType],...extraClients.map((r,i)=>[`ลูกความ ${i+2}`,r.name]),['ทนายหลัก',state.lawyer],['ผู้ช่วย',buddies.join(', ')||'ยังไม่มอบหมาย']]],['การเงินและนัดหมาย',[['ทุนทรัพย์',state.amount],['รายได้โดยประมาณ',state.estimatedFee],['ประมาณการค่าใช้จ่าย',costTotal()],['หน่วยน้ำหนัก',state.weightUnit],['สกุลเงินยอดเรียกร้อง',state.claimCurrency],['วันเริ่มนับอายุความ',state.timeBarStart],['วันครบกำหนดที่ยืนยัน',state.timeBarConfirmed],['เหตุผลการนับ',state.timeBarBasis],...costs.map(c=>[c.label,`${c.quantity||'ยังไม่ระบุ'} × ${c.rate||'ยังไม่ระบุอัตรา'}`]),['เพิ่มนัดแรก',state.initialActivity?'ใช่':'ไม่'],['หัวข้อ',state.activityTitle],['ประเภท',state.activityType],['วันเวลา',state.activityAt],['รายละเอียดนัด',state.activityDescription],['ไฟล์แนบ',uploadedFiles.map(f=>f.name).join(', ')||'ยังไม่มี']]]];if(state.type==='ขนส่ง / Cargo claim'){groups.push(['ข้อมูล Cargo claim',cargoFields.map(([key,label])=>[label,state[key]])]);groups.push(['ผลพิจารณา',considerations.map(c=>[`${c.no}. ${c.original}`,`${c.status} · ${c.answer||'ยังไม่มีข้อสรุป'} · ${c.note} · ${c.evidence}`])]);groups.push(['เช็กลิสต์เอกสาร',claimDocs.map(d=>[d.label,`${d.status} · ${d.file||'ยังไม่ผูกไฟล์'} · ${d.remark} · ${d.review}`])])}const m=document.getElementById('modal');m.classList.add('wide');m.innerHTML=`<h2>ตรวจสอบข้อมูลครบก่อนเปิดแฟ้ม</h2><p class="data-note">ข้อมูลจำลอง · ไม่ส่งข้อมูลหรือสร้างคดีในระบบจริง</p><div class="summary-review">${groups.map(([title,rows],i)=>fold(title,viewValues(rows),i===0)).join('')}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').close()">กลับไปแก้ไข</button><button class="btn primary" onclick="document.getElementById('modal').close();state.stage='รับเรื่อง';state.caseStatus='คดีใหม่';setPage('detail');toast('เปิดแฟ้มตัวอย่างแล้ว · ยังไม่ได้ยื่นฟ้อง')">สร้างคดีตัวอย่าง</button></div>`;m.showModal()};
function showSources(index=0){const m=document.getElementById('modal');m.classList.add('wide');m.innerHTML=`<div class="row between"><h2>เอกสารอ้างอิงต้นฉบับ</h2><button aria-label="ปิดต้นฉบับ" onclick="document.getElementById('modal').close()">×</button></div><p class="data-note">ข้อความจาก Excel ทั้งสามไฟล์พร้อมตำแหน่งเซลล์ · ไม่เปลี่ยนเลขข้อหรือเติมผลพิจารณา</p><div class="summary-review">${sourceBooks.map((book,i)=>fold(esc(book.name),book.sheets.map(s=>`<h3>${esc(s.name)}</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>เซลล์</th><th>ข้อความต้นฉบับ</th></tr></thead><tbody>${s.rows.flatMap(r=>r.cells.map(c=>`<tr><td>${c.cell}</td><td>${esc(c.value)}</td></tr>`)).join('')}</tbody></table></div>`).join(''),index===i)).join('')}</div>`;if(!m.open)m.showModal()}
function registryDialog(){genericDialog('สร้างทะเบียนลูกค้าตัวอย่าง',`<div class="fields">${field('registryName','ชื่อ')}${selectField('registryType','ประเภท',['บุคคลธรรมดา','นิติบุคคล'])}${field('registryContact','ผู้ติดต่อ')}${field('registryPhone','โทรศัพท์')}${field('registryEmail','อีเมล','email')}</div>`,"state.customer=state.registryName||state.customer;state.contact=state.registryContact||state.contact;if(state.same)state.client=state.customer;")}
function genericDialog(title,body,save=''){const m=document.getElementById('modal');m.classList.add('wide');m.innerHTML=`<h2>${title}</h2><p class="data-note">เก็บค่าเพื่อทดลอง UI ในหน้านี้เท่านั้น</p><div class="summary-review">${body}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').close()">ปิด</button><button class="btn primary" onclick="${save}document.getElementById('modal').close();render();writeLocal()">เก็บค่าในตัวอย่าง</button></div>`;if(!m.open)m.showModal()}
function showSuggestion(){genericDialog('ข้อเสนอจากเอกสาร',`<p class="data-note">ตัวอย่างโครงร่างสำหรับตรวจข้อเสนอ ไม่มีการวิเคราะห์ AI จริง</p>${viewValues([['ฟิลด์','ชื่อคดี / ศาล / ทุนทรัพย์'],['ค่าปัจจุบัน',state.title],['ข้อเสนอ','ยังไม่มี — ต้องอ่านไฟล์จริงก่อนเสนอ'],['แหล่งอ้างอิง','ชื่อเอกสาร เลขหน้า และข้อความต้นฉบับ'],['การใช้ค่า','เลือกยืนยันเป็นรายฟิลด์ ไม่เขียนทับอัตโนมัติ']])}`)}
function allCaseData(){return `<div class="block-title"><h2>ข้อมูลคดีทั้งหมด</h2><button class="link" onclick="setPage('create')">แก้ไขข้อมูล</button></div>${viewValues([['ชื่อคดี',state.title],['เลขอ้างอิงสำนักงาน','ตัวอย่าง / 2569-0042'],['เลขแฟ้ม','MOCK-0042'],['เลขอ้างอิงลูกค้า',state.customerRef],['ประเภทคดี',state.type],['สถานะงาน',state.caseStatus],['ขั้นตอนคดี',state.stage],['ผลคดี',state.outcome],['ฝ่ายเรา',state.partyRole],['ศาล',state.court],['ระดับศาล',state.courtLevel],['เลขดำ',state.number],['เลขแดง',state.redNumber],['วันที่เปิด',state.openedAt],['วันที่ปิด',state.closedAt],['ทุนทรัพย์',state.amount],['รายได้โดยประมาณ',state.estimatedFee],['อายุความ',state.limitationDeadline],['รายละเอียดคดี',state.description],['สรุปปิดคดี',state.closingSummary],...customItems.map(r=>[r.label,r.value])])}${fold('ผู้มอบหมาย ลูกความ และทีม',peopleForm()+teamForm())}${fold('ประมาณการค่าใช้จ่าย',costsForm())}`}
function noticePanel(){return `<h2>หนังสือทวงถามและงานก่อนฟ้อง</h2><p class="data-note">คงความเชื่อมโยงกับเรื่องรับเข้าต้นทาง · วันตอบกลับหนังสือไม่ใช่วันครบอายุความ</p><div class="fields">${field('intakeRef','เรื่องรับเข้าต้นทาง')}${field('noticeRecipient','ผู้รับหนังสือ')}${field('noticeIssuedAt','วันที่ออก Notice','date')}${field('noticeDeadline','วันครบกำหนดตามหนังสือ','date')}${field('noticeResult','ผล / หมายเหตุ','textarea')}${selectField('preLitigationStatus','สถานะงานก่อนฟ้อง',['ยังไม่เริ่ม','เตรียม Notice','ส่ง Notice แล้ว','อยู่ระหว่างพิจารณา','จัดทำรายงาน','ได้รับข้อเสนอ','กำลังเจรจา','พิจารณาอุทธรณ์','พร้อมยื่นฟ้อง','ยุติจากการตกลง','ยุติโดยไม่ฟ้อง'])}${field('offer','ข้อเสนอจ่ายล่าสุด (บาท)','number')}${field('preNotes','บันทึกงานก่อนฟ้อง','textarea')}</div><div class="extra-actions"><button class="btn" onclick="writeLocal()">เก็บบันทึก</button><button class="btn" onclick="toast('แสดงตัวอย่างร่างเท่านั้น — ไม่มีการส่งหนังสือ')">ร่าง Notice / ดูประวัติ</button></div>`}
function insurancePanel(){return `<h2>ประกันภัย</h2><p class="data-note">ข้อมูลติดตามเคลมเดิมและค่าเฉพาะ Cargo ใช้เลขกรมธรรม์ / เลขเคลมเดียวกัน</p><div class="fields">${field('insurerName','บริษัทประกัน')}${field('policyNumber','เลขกรมธรรม์')}${field('claimNumber','เลขเคลม')}${field('incidentDate','วันวินาศภัย','date')}${field('claimedDate','วันที่ยื่นเคลม','date')}${selectField('insuranceStage','ขั้นตอนเคลม',['ยื่นเคลม','ปฏิเสธ / จ่ายบางส่วน','หนังสือทวงถาม','ร้องเรียน คปภ.','ดำเนินคดี'])}${field('denialReason','เหตุผลปฏิเสธ / จ่ายบางส่วน','textarea')}${field('demandLetterSentAt','วันที่ส่งหนังสือทวงถาม','date')}${field('demandLetterDeadline','กำหนดตอบหนังสือทวงถาม','date')}${field('oicComplaintNumber','เลขคำร้อง คปภ.')}${field('oicComplaintDate','วันที่ร้องเรียน คปภ.','date')}${field('oicOutcome','ผล คปภ.','textarea')}${field('insuranceLimitationDeadline','วันครบอายุความของเคลมที่ตรวจแล้ว','date')}</div><button class="btn primary" style="margin-top:20px" onclick="writeLocal()">เก็บข้อมูลในตัวอย่าง</button>`}
const participantFields=[['name','ชื่อ–นามสกุล'],['nickname','ชื่อเล่น'],['role','บทบาท'],['side','ฝ่าย'],['personType','ประเภทบุคคล'],['idNumber','เลขประจำตัว'],['address','ที่อยู่'],['phone','โทรศัพท์'],['email','อีเมล'],['opposingLawyer','ทนายฝ่ายตรงข้าม'],['opposingInsurer','ประกันฝ่ายตรงข้าม'],['medicalLicenseNo','เลขใบอนุญาตแพทย์'],['notes','หมายเหตุ']];
function participantsPanel(){return `<div class="block-title"><h2>คู่ความและผู้เกี่ยวข้อง</h2><button class="link" onclick="participants.push({});render()">+ เพิ่มคู่ความ</button></div><p class="data-note">แยกบทบาทคู่ความจากผู้มอบหมายงาน / ผู้จ่ายเงิน</p>${participants.length?participants.map((p,i)=>`<section class="cargo-review-row"><h3>รายที่ ${i+1}</h3><div class="fields">${participantFields.map(([k,l])=>`<div class="field"><label for="party-${i}-${k}">${l}</label><input id="party-${i}-${k}" value="${esc(p[k]||'')}" oninput="participants[${i}]['${k}']=this.value"></div>`).join('')}</div></section>`).join(''):'<p class="muted">ยังไม่มีคู่ความในตัวอย่าง กดเพิ่มเพื่อดูฟิลด์ครบตามแบบเดิม</p>'}`}
function calendarPanel(){return `<div class="block-title"><h2>ไทม์ไลน์และนัดหมาย</h2><button class="link" onclick="newAppointment()">+ เพิ่มนัดหมาย</button></div><div class="data-toolbar"><button class="btn" onclick="toast('มุมมองรายการนัดใน mockup')">รายการ</button><button class="btn" onclick="toast('ตัวแทนปฏิทินรายเดือนในระบบจริง')">ปฏิทิน</button></div>${appointments.map(a=>`<div class="record-row"><h3>${esc(a.title||'ยังไม่ระบุหัวข้อ')}</h3><p class="muted small">${esc(a.date)} · ${esc(a.type)}</p><p>${esc(a.description||'')}</p></div>`).join('')}${activity()}${fold('ผลหลังขึ้นศาล',`<div class="fields">${field('hearingEvent','นัดศาลที่อ้างอิง')}${field('hearingOutcome','ผลการขึ้นศาล','textarea')}${field('hearingNext','นัดถัดไป','datetime-local')}${field('hearingFollowup','งานที่ต้องทำต่อ','textarea')}</div>`)}${fold('กำหนดเวลาที่เสนอจากเอกสาร',viewValues([['แหล่งอ้างอิง','เอกสาร / หน้า'],['วันที่เสนอ','ยังไม่มี'],['วันที่ทนายยืนยัน','ยังไม่มี'],['สถานะ','รอตรวจ ไม่ยืนยันอัตโนมัติ']]))}`}
function billingPanel(){return `<h2>ค่าใช้จ่ายและการเงินคดี</h2>${viewValues([['รายได้',state.estimatedFee],['ค่าใช้จ่ายอนุมัติ','ยังไม่มีข้อมูลตัวอย่าง'],['กำไร','ยังไม่คำนวณ'],['ชั่วโมงเรียกเก็บ','ยังไม่มี'],['ยอดเวลาเรียกเก็บ','ยังไม่มี'],['ค่าใช้จ่ายทั้งหมด','ยังไม่มี']])}${fold('ประมาณการค่าใช้จ่าย',costsForm())}${fold('รายการเบิกค่าใช้จ่าย',`<div class="fields">${field('expenseAmount','จำนวนเงิน','number')}${field('expenseCategory','หมวดค่าใช้จ่าย')}${field('expenseDescription','รายละเอียด')}${field('expensePurpose','วัตถุประสงค์')}${field('expenseDate','วันที่','date')}${field('expenseUser','ผู้เบิก')}${selectField('expenseStatus','สถานะ',['ร่าง','รออนุมัติ','อนุมัติ','ปฏิเสธ'])}${selectField('expensePayer','ผู้รับค่าใช้จ่าย',['เรียกเก็บลูกค้า','สำนักงานออกเอง'])}</div>${filePicker()}`)}${fold('บันทึกเวลาทำงาน',`<div class="fields">${field('timeDate','วันที่ทำงาน','date')}${field('timeUser','ผู้ทำงาน')}${field('timeDescription','งานที่ทำ')}${field('timeHours','จำนวนชั่วโมง','number')}${field('timeRate','อัตราต่อชั่วโมง','number')}</div>`)}${fold('ใบแจ้งหนี้',`<div class="fields">${field('invoiceCustomer','ผู้รับใบแจ้งหนี้')}${field('invoiceNumber','เลขใบแจ้งหนี้')}${field('invoiceAmount','ยอดใบแจ้งหนี้','number')}${field('invoiceDate','วันที่ออก','date')}${field('invoiceDue','ครบกำหนดชำระ','date')}${selectField('invoiceStatus','สถานะ',['ร่าง','ออกแล้ว','ชำระบางส่วน','ชำระแล้ว'])}</div>`)}<p class="data-note">เป็นพื้นที่แสดงและกรอกข้อมูล ไม่มีการส่งเบิกหรือออกใบแจ้งหนี้จริง</p>`}
function aiPanel(){return `<h2>ข้อเท็จจริงและฎีกา</h2><p class="data-note">คงการเลือกเอกสารต้นทาง การอ้างหน้า และการตรวจรับผลโดยทนาย</p>${field('askQuestion','คำถามจากสำนวน','textarea')}${filePicker()}${fold('คำตอบและหลักฐานอ้างอิง',viewValues([['คำตอบ','ยังไม่มีผลวิเคราะห์'],['ข้อความต้นทาง','รอเลือกเอกสาร'],['เอกสาร / หน้า','ยังไม่ระบุ'],['สถานะตรวจ','รอตรวจ']]))}${fold('สรุปและไทม์ไลน์ข้อเท็จจริง',field('factsSummary','สรุปข้อเท็จจริง','textarea')+field('factsTimeline','เหตุการณ์ / วันเวลา / แหล่งอ้างอิง','textarea'))}${fold('ฎีกาและบทกฎหมายที่เกี่ยวข้อง',field('precedentRefs','เลขฎีกา / URL ฉบับเต็ม / ประเด็น','textarea')+field('statuteRefs','บทกฎหมาย / แหล่งอ้างอิง','textarea'))}${fold('ข้อมูลพร้อมร่าง Notice',field('noticeFacts','ข้อเท็จจริงสำหรับร่าง Notice','textarea'))}<button class="btn" onclick="toast('Mockup เท่านั้น — ไม่เรียก AI และไม่ใช้เครดิต')">แสดงพื้นที่วิเคราะห์</button>`}
function closingPanel(){return `<h2>รายงานปิดงาน / ร่างอีเมล</h2><p class="data-note">เลือกเหตุการณ์ ตรวจแก้ข้อความ และอนุมัติร่างแต่ละเวอร์ชันก่อนใช้ · ไม่มีการส่งอีเมลใน mockup</p>${field('closingActivities','เหตุการณ์ที่เลือกใช้','textarea')}${field('closingSubject','หัวข้ออีเมล')}${field('closingBody','เนื้อหาอีเมล','textarea')}${viewValues([['สถานะร่าง',state.closingApproval],['เวอร์ชัน','ตัวอย่าง v1']])}<div class="extra-actions"><button class="btn" onclick="writeLocal('เก็บร่างในตัวอย่างแล้ว — ยังไม่ได้ส่ง')">เก็บร่าง</button><button class="btn" onclick="state.closingApproval='อนุมัติร่างตัวอย่างแล้ว';render()">อนุมัติร่างตัวอย่าง</button></div>${fold('ปิดคดี',`<p class="data-note">คงเงื่อนไขตรวจงานค้าง ยอดค้างชำระ และสรุปผลก่อนปิด</p>${field('closingSummary','สรุปผลคดี','textarea')}${field('closedAt','วันที่ปิด','date')}${selectField('outcome','ผลคดี',['ยังไม่ระบุ','ชนะ','แพ้','ตกลงยอมความ','ไกล่เกลี่ยสำเร็จ','ถอนฟ้อง','อยู่ระหว่างดำเนินการ'])}${toggleField('ackOutstanding','รับทราบยอดค้างชำระที่ตรวจแล้ว')}<button class="btn" onclick="toast('ต้องตรวจงานค้างและยอดจริงก่อนปิด — ตัวอย่างนี้ไม่ปิดคดีจริง')">ตรวจสอบก่อนปิดคดี</button>`)}`}
function notesPanel(){return `<h2>บันทึกย่อและการติดต่อ</h2>${field('notes','บันทึกย่อ','textarea')}<button class="btn" onclick="writeLocal()">เก็บบันทึกย่อ</button>${fold('สายติดต่อลูกความ',`${messages.map(m=>`<div class="record-row"><p>${esc(m.text)}</p><small class="muted">${esc(m.at)} · ผู้บันทึกในตัวอย่าง</small></div>`).join('')}${field('newMessage','ข้อความติดต่อ / บันทึกสาย','textarea')}<button class="btn" onclick="if(state.newMessage?.trim()){messages.push({text:state.newMessage,at:new Date().toLocaleString('th-TH')});state.newMessage='';render();toast('เก็บข้อความจำลองแล้ว ไม่ส่งให้บุคคลอื่น')}">เก็บข้อความในตัวอย่าง</button>`,true)}`}
function checklistPanel(){return `<h2>เช็กลิสต์และ Playbook</h2>${selectField('playbook','Playbook ที่ใช้',['ยังไม่เลือก','Corporate · v1','Criminal · v1','คดีทางการแพทย์ · v1','Cargo checklist · ตัวอย่างจาก Excel'])}<p class="data-note">งานและเอกสารที่ต้องมีแยกกัน การมีไฟล์ไม่เท่ากับผ่านการตรวจ</p>${baseTasks()}<button class="btn" onclick="activeTab='Cargo claim';cargoSub='เอกสาร 16 รายการ';render()">เปิดเช็กลิสต์เอกสาร Cargo</button>`}
tasksHtml=function(){return `<div class="data-toolbar">${selectField('taskFilterStatus','สถานะงาน',['ทุกสถานะ','ยังไม่เริ่ม','กำลังทำ','รอ Senior ตรวจ','ต้องแก้ไข','เสร็จแล้ว'])}${selectField('taskFilterPerson','ผู้รับผิดชอบ',['ทุกคน','ฉันเอง','ยังไม่มอบหมาย'])}</div><p class="data-note">ตัวอย่างตำแหน่งตัวกรอง — รายการด้านล่างยังแสดงงานทั้งหมด</p>${baseTasks()}${fold('ข้อมูลงานเพิ่มเติม',`<div class="fields">${field('taskDescription','รายละเอียดงาน','textarea')}${selectField('taskPriority','ความสำคัญ',['สูง','กลาง','ต่ำ'])}${field('taskDue','วันครบกำหนด','date')}${field('taskOwner','ผู้รับผิดชอบ')}${field('taskAttachments','เอกสารแนบงาน')}</div>`)}`};
docsHtml=function(){return `${baseDocs()}${fold('อัปโหลดและจัดหมวดเอกสาร',filePicker(),true)}${fold('หมวดหมู่ เวอร์ชัน และการตรวจเอกสาร',`<div class="fields">${field('documentCategory','หมวดหมู่')}${field('documentVersion','เวอร์ชัน')}${selectField('documentReview','สถานะตรวจเวอร์ชัน',['ร่าง','รอตรวจ','ต้องแก้ไข','อนุมัติ'])}${field('documentReviewer','ผู้ตรวจ')}${field('documentTemplate','แม่แบบเอกสาร')}${field('documentReviewNotes','หมายเหตุการตรวจ','textarea')}</div>`)}<button class="btn" onclick="activeTab='Cargo claim';cargoSub='เอกสาร 16 รายการ';render()">เช็กลิสต์เอกสาร Cargo 16 รายการ</button>`};
const mainTabs=['ภาพรวม','งาน','ไทม์ไลน์','เอกสาร','Cargo claim','ค่าใช้จ่าย'];
panel=function(){if(activeTab==='ภาพรวม')return `<div class="block-title"><h2>งานถัดไปในสำนวน</h2><button class="link" onclick="setSecondary('ข้อมูลคดี')">ข้อมูลคดีทั้งหมด ↗</button></div>${baseTasks()}<div class="rich-notes"><div class="row between"><h3>Cargo claim</h3><button class="link" onclick="activeTab='Cargo claim';render()">เปิดพื้นที่พิจารณา ↗</button></div><p class="muted small" style="margin-top:8px">ข้อมูลเคลม · ประเด็นพิจารณา 12 แถว · เอกสาร 16 รายการ</p><p class="small" style="margin-top:7px">อายุความ: ${esc(state.timeBarConfirmed||'ยังไม่ได้ยืนยัน')} · เอกสาร: ${claimDocs.filter(d=>d.status==='Yes').length}/16</p></div>${baseDocs()}${activity()}`;if(activeTab==='งาน')return tasksHtml();if(activeTab==='ไทม์ไลน์')return calendarPanel();if(activeTab==='เอกสาร')return docsHtml();if(activeTab==='ค่าใช้จ่าย')return billingPanel();if(activeTab==='Cargo claim')return `<div class="subnav" aria-label="ส่วนของ Cargo claim">${['ข้อมูลเคลม','พิจารณา 12 แถว','เอกสาร 16 รายการ'].map(t=>`<button class="${cargoSub===t?'active':''}" onclick="cargoSub='${t}';render()">${t}</button>`).join('')}</div>${cargoSub==='ข้อมูลเคลม'?cargoData():cargoSub==='พิจารณา 12 แถว'?considerationPanel():cargoDocsPanel()}`;return ({'ข้อมูลคดี':allCaseData,'คู่ความ':participantsPanel,'ประกันภัย':insurancePanel,'Notice / ก่อนฟ้อง':noticePanel,'ข้อเท็จจริงและฎีกา':aiPanel,'รายงานปิดงาน':closingPanel,'บันทึกและการติดต่อ':notesPanel,'เช็กลิสต์ / Playbook':checklistPanel}[secondary]||allCaseData)()};
detailPage=function(){return `<div class="detail-heading"><div><div class="row"><span class="eyebrow" style="margin:0">MATTER · ตัวอย่าง 2569 / 0042</span><span class="pill">${esc(state.stage)}</span></div><h1>${esc(state.title)}</h1><div class="case-meta"><span>${esc(state.client)}</span><span>· ${esc(state.type)}</span></div></div><button class="btn" onclick="manageCase()">${icon('settings')}<span>จัดการคดี</span></button></div><div class="core-strip"><span>สถานะงาน <b>${state.caseStatus}</b></span><span>ผู้รับผิดชอบ <b>${state.lawyer}</b></span><span>อายุความ <b>${esc(state.timeBarConfirmed||state.limitationDeadline||'ยังไม่ได้ยืนยัน')}</b></span><button class="link" onclick="showSources(0)">เอกสารตัวอย่าง 3 ไฟล์ ↗</button></div><section class="next-action"><div><div class="eyebrow">งานสำคัญถัดไป</div><h2>ตรวจเอกสารและประเด็นความรับผิด</h2><p>ยังไม่มีนัดศาลในตัวอย่างนี้ · ข้อมูลเคลมและงานก่อนฟ้องอยู่ในสำนวนเดียวกัน</p></div><button class="btn" onclick="activeTab='Cargo claim';render()">เปิดพิจารณา Cargo ${icon('arrow')}</button></section><div class="detail-layout"><nav class="tabs" aria-label="ส่วนของคดี">${mainTabs.map(t=>`<button class="tab ${t===activeTab?'active':''}" aria-current="${t===activeTab?'page':'false'}" onclick="activeTab='${t}';render()">${t}</button>`).join('')}<select class="secondary-menu" aria-label="ส่วนงานอื่นของคดี" onchange="setSecondary(this.value)"><option disabled ${activeTab!=='ส่วนอื่น'?'selected':''}>ข้อมูลและส่วนงานอื่น</option>${['ข้อมูลคดี','คู่ความ','ประกันภัย','Notice / ก่อนฟ้อง','ข้อเท็จจริงและฎีกา','รายงานปิดงาน','บันทึกและการติดต่อ','เช็กลิสต์ / Playbook'].map(t=>`<option ${activeTab==='ส่วนอื่น'&&secondary===t?'selected':''}>${t}</option>`).join('')}</select></nav><div class="detail-grid ${activeTab!=='ภาพรวม'?'wide-panel':''}"><main class="work-main">${panel()}</main>${fullFileMeta()}</div></div>`};
manageCase=function(){genericDialog('สถานะและขั้นตอนคดี',`<p class="data-note">สถานะงานและขั้นตอนคดีเป็นคนละค่า การเปิดแฟ้มไม่เปลี่ยนเป็นยื่นฟ้อง</p><div class="fields">${selectField('caseStatus','สถานะงาน',['คดีใหม่','กำลังร่าง','กำลังดำเนินการ','นัดศาล','รอดำเนินการ','ปิดคดี','จัดเก็บ'])}${selectField('stage','ขั้นตอนคดี',['รับเรื่อง','รวบรวมข้อเท็จจริง','ก่อนฟ้อง','ยื่นฟ้อง','ไกล่เกลี่ย','สืบพยาน','รอคำพิพากษา','บังคับคดี','ปิดคดี'])}${field('limitationDeadline','อายุความที่ตรวจแล้ว','date')}${selectField('partyRole','ฝ่ายเรา',['ยังไม่ระบุ','โจทก์','จำเลย'])}</div><div class="extra-actions"><button class="link" onclick="document.getElementById('modal').close();setSecondary('รายงานปิดงาน')">รายงานและตรวจสอบก่อนปิดคดี ↗</button><button class="link" onclick="document.getElementById('modal').close();activeTab='ไทม์ไลน์';render()">นัดหมาย / ผลหลังขึ้นศาล ↗</button></div>`)};
// Restore authoritative mutations for synchronized customer/client labels in this mockup.
saveValue=function(k,v){state[k]=v;if(k==='customer'&&state.same){state.client=v;const el=document.getElementById('rich-client');if(el)el.value=v}if(k==='client'&&state.autoTitle){state.title=state.type+' — '+v;const el=document.getElementById('rich-title');if(el)el.value=state.title}updateSummary()};
function newAppointment(){state.initialActivity=true;genericDialog('เพิ่มนัดหมาย',appointmentForm(),"appointments.push({title:state.activityTitle,date:state.activityAt,type:state.activityType,description:state.activityDescription});")}
function newActivity(){genericDialog('เพิ่มกิจกรรม',field('activityTitle','หัวข้อ')+field('activityAt','วันเวลา','datetime-local')+field('activityDescription','รายละเอียด','textarea'),"appointments.push({title:state.activityTitle,date:state.activityAt,description:state.activityDescription});")}
function fullFileMeta(){return state.amount===''?baseFileMeta().replace('0 บาท','ยังไม่ระบุ'):baseFileMeta()}
customForm=function(){return `<p class="section-caption">พื้นที่แทนฟิลด์ตาม fieldSchema ของประเภทคดี — คงทั้งชนิดข้อมูลและค่า</p>${customItems.map((r,i)=>`<div class="record-row"><div class="fields"><div class="field"><label for="custom-label-${i}">ชื่อฟิลด์</label><input id="custom-label-${i}" value="${esc(r.label)}" oninput="customItems[${i}].label=this.value"></div><div class="field"><label for="custom-type-${i}">ชนิดข้อมูล</label><select id="custom-type-${i}" onchange="customItems[${i}].type=this.value;render()">${['text','number','date','select'].map(t=>`<option ${t===(r.type||'text')?'selected':''}>${t}</option>`).join('')}</select></div><div class="field full"><label for="custom-value-${i}">ค่า</label>${r.type==='select'?`<select id="custom-value-${i}" onchange="customItems[${i}].value=this.value">${['ยังไม่ระบุ',...(r.options||'ตัวเลือก A,ตัวเลือก B').split(',')].map(t=>`<option ${r.value===t?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input id="custom-value-${i}" type="${r.type||'text'}" value="${esc(r.value)}" oninput="customItems[${i}].value=this.value">`}</div></div></div>`).join('')}<button type="button" class="link" onclick="customItems.push({label:'',value:'',type:'text'});render()">+ เพิ่มฟิลด์ตามประเภทคดี</button>`};
activity=function(){return `<section style="margin-top:26px"><div class="block-title"><h2>ความเคลื่อนไหวคดี</h2><button type="button" class="link" onclick="newActivity()">+ เพิ่มกิจกรรม</button></div><div class="timeline"><div class="event">เปิดแฟ้มตัวอย่างเพื่อพิจารณา Cargo claim<small>22 ก.ย. 2569 · ยังไม่ยื่นฟ้อง</small></div>${appointments.map(a=>`<div class="event">${esc(a.title||'ยังไม่ระบุหัวข้อ')}<small>${esc(a.date)} · ${esc(a.description||'')}</small></div>`).join('')}</div></section>`};
// Default non-submit buttons remain safe when the same panels are inside Create's form.
const renderWithData=render;
render=function(){const openKeys=new Set(Array.from(document.querySelectorAll('#app details[open]')).map(d=>d.querySelector('summary')?.textContent));renderWithData();document.querySelectorAll('#app button:not([type])').forEach(b=>b.type='button');document.querySelectorAll('#app details').forEach(d=>{if(openKeys.has(d.querySelector('summary')?.textContent))d.open=true})};
nextCreate=function(){if(!state.title.trim()){if(variant==='B')step=0;render();toast('กรุณาระบุชื่อคดี');document.getElementById('rich-title')?.focus();return}if(variant==='B'&&step<2){step++;render();return}showReview()};
// Fast-create revision: detailed work starts after opening the matter.
state.type='Litigation';state.title='';state.policyRef='';state.ourRef='';
const isCargo=()=>state.type==='ขนส่ง / Cargo claim';
function assistantForm(){return `<p class="small">ทนายผู้ช่วย — เลือกได้หลายคน</p>${['อรณิชา วัฒนกุล','ธนกร เจริญกิจ','ณัฐชา ศิริกุล'].filter(t=>t!==state.lawyer).map(t=>`<label class="quiet-check"><input type="checkbox" ${buddies.includes(t)?'checked':''} onchange="if(this.checked)buddies.push('${t}');else buddies.splice(buddies.indexOf('${t}'),1)">${t}</label>`).join('')}`}
function costAmount(c){if(c.quantity===''||c.rate==='')return null;const q=Number(c.quantity),r=Number(c.rate);return Number.isFinite(q)&&Number.isFinite(r)&&q>=0&&r>=0?Math.round(q*r*100)/100:null}
costTotal=function(){const amounts=costs.map(costAmount);return amounts.every(x=>x===null)?'ยังไม่ได้ประมาณการ':`${amounts.reduce((s,x)=>s+(x??0),0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})} บาท${amounts.some(x=>x===null)?' · ยังไม่ครบทุกอัตรา':''}`};
costsForm=function(){return `<p class="data-note">คำนวณจำนวน × อัตราให้แต่ละรายการ และรวมยอดอัตโนมัติ</p><div class="table-wrap"><table class="data-table"><thead><tr><th>รายการ</th><th>จำนวน</th><th>อัตรา / บาท</th><th>รวม / บาท</th><th></th></tr></thead><tbody>${costs.map((c,i)=>`<tr><td><input aria-label="รายการค่าใช้จ่าย ${i+1}" value="${esc(c.label)}" oninput="costs[${i}].label=this.value"></td><td><input type="number" min="0" aria-label="จำนวน ${i+1}" value="${c.quantity}" oninput="costs[${i}].quantity=this.value;refreshCosts()"></td><td><input type="number" min="0" step="0.01" aria-label="อัตรา ${i+1}" value="${c.rate}" oninput="costs[${i}].rate=this.value;refreshCosts()"></td><td data-cost-row="${i}">${costAmount(c)===null?'ยังไม่ครบ':costAmount(c).toLocaleString('th-TH')}</td><td><button type="button" class="link" onclick="costs.splice(${i},1);render()">ลบ</button></td></tr>`).join('')}</tbody></table></div><div class="row between"><button type="button" class="link" onclick="costs.push({label:'',quantity:'1',rate:''});render()">+ เพิ่มรายการค่าใช้จ่าย</button><span id="cost-total" class="estimate-total">${costTotal()}</span></div>`};
refreshCosts=function(){document.querySelectorAll('[data-cost-row]').forEach(e=>{const value=costAmount(costs[Number(e.dataset.costRow)]);e.textContent=value===null?'ยังไม่ครบ':value.toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})});const e=document.getElementById('cost-total');if(e)e.textContent=costTotal()};
function payerContact(i){const main=i===undefined,id=main?'rich-contact':`extraCustomers-${i}-contact`,value=main?state.contact:extraCustomers[i].contact;const options=[...new Set(['','คุณปรียา · ฝ่ายกฎหมาย','คุณกมล · ฝ่ายสินไหม (ตัวอย่าง)',value||''])];return `<div class="field"><label for="${id}">ผู้ติดต่อ</label><select id="${id}" onchange="${main?'state.contact':`extraCustomers[${i}].contact`}=this.value">${options.map(v=>`<option value="${esc(v)}" ${v===(value||'')?'selected':''}>${esc(v||'เลือกผู้ติดต่อ')}</option>`).join('')}</select></div>`}
function payerShare(i){const main=i===undefined,id=main?'rich-customerShare':`extraCustomers-${i}-share`,value=main?state.customerShare:extraCustomers[i].share;return `<div class="field"><label for="${id}">สัดส่วนการจ่าย (%)</label><input id="${id}" type="number" min="0" max="100" step="0.01" placeholder="ยังไม่ระบุ" value="${esc(value??'')}" oninput="${main?'state.customerShare':`extraCustomers[${i}].share`}=this.value;refreshPayerTotal()"></div>`}
function payerTotal(){const values=[state.customerShare,...extraCustomers.map(r=>r.share)];const set=values.filter(v=>v!==''&&v!==undefined&&v!==null);if(!set.length)return 'สัดส่วนการจ่ายรวม: ยังไม่ระบุ';if(set.some(v=>!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100))return 'กรุณาระบุสัดส่วนแต่ละรายระหว่าง 0–100%';const total=Math.round(set.reduce((n,v)=>n+Number(v),0)*100)/100;return `สัดส่วนการจ่ายรวม ${total}% · ${set.length<values.length?'ยังระบุไม่ครบทุกคน':total===100?'ครบ 100%':total<100?'เหลืออีก '+Math.round((100-total)*100)/100+'%':'เกิน 100% กรุณาตรวจสอบ'}`}
function refreshPayerTotal(){const el=document.getElementById('payer-total');if(el)el.textContent=payerTotal()}
repeatRows=function(kind,arr){return arr.map((r,i)=>`<div class="record-row ${kind==='extraClients'?'client-record':''}"><div class="record-heading"><button type="button" class="remove" onclick="${kind}.splice(${i},1);render()">ลบรายที่ ${i+2}</button><h3>${kind==='extraCustomers'?'ผู้มอบหมาย':'ลูกความ'}รายที่ ${i+2}</h3></div><div class="fields ${kind==='extraCustomers'?'payer-fields':''}"><div class="field"><label for="${kind}-${i}-name">ชื่อ</label><input id="${kind}-${i}-name" value="${esc(r.name||'')}" oninput="${kind}[${i}].name=this.value"></div>${kind==='extraCustomers'?`${payerContact(i)}${payerShare(i)}`:''}</div></div>`).join('')};
peopleForm=function(){return `<div class="fields payer-fields">${field('customer','ผู้มอบหมายงาน / ผู้จ่ายเงิน')}${payerContact()}${payerShare()}</div>${repeatRows('extraCustomers',extraCustomers)}<p class="helper" id="payer-total" style="margin-top:16px">${payerTotal()}</p><div class="extra-actions"><button type="button" class="link" onclick="extraCustomers.push({name:'',contact:'',share:''});render()">+ เพิ่มผู้มอบหมาย</button><button type="button" class="link" onclick="registryDialog()">+ สร้างทะเบียนลูกค้า</button></div><hr class="section-separator"><h3 class="client-subheading">ลูกความที่สำนักงานดูแล</h3>${toggleField('same','ลูกความคนเดียวกับผู้มอบหมาย',"if(state.same)state.client=state.customer;render()")}${!state.same?'<div class="primary-client-fields">'+field('client','ลูกความหลัก')+toggleField('unknownClient','ยังไม่ทราบชื่อลูกความ')+selectField('clientType','ประเภทลูกความใหม่',['นิติบุคคล','บุคคลธรรมดา'])+'</div>':'<p class="helper">ใช้ข้อมูลผู้มอบหมายเป็นลูกความหลัก</p>'}${repeatRows('extraClients',extraClients)}<button type="button" class="link" style="margin-top:12px" onclick="extraClients.push({name:''});render()">+ เพิ่มลูกความอีกราย</button>`};
customForm=function(){return `<p class="helper">ฟิลด์เฉพาะจะแสดงตามประเภทคดีที่สำนักงานตั้งไว้</p>${customItems.map(r=>viewValues([[r.label,r.value]])).join('')}`};
createPage=function(){return `<div class="page-heading"><div class="eyebrow">NEW MATTER</div><h1>เปิดคดีใหม่</h1><p class="muted small">ระบุเรื่อง ผู้มอบหมาย และคนรับผิดชอบ แล้วเริ่มทำงานได้เลย</p></div><div class="new-layout fast-create"><form class="paper" onsubmit="event.preventDefault();nextCreate()"><section class="form-section focus-current" aria-labelledby="create-case-heading"><div class="section-head"><div><h2 id="create-case-heading">ข้อมูลคดี</h2><p>ชื่อเรื่อง ประเภท และเลขอ้างอิงสำหรับค้นหา</p></div></div><div class="fields matter-basics"><div class="field"><label for="rich-type">ประเภทคดี</label><select id="rich-type" onchange="state.type=this.value;render()">${['Corporate','Criminal','Family Law','Intellectual Property','Litigation','การแพทย์','ขนส่ง / Cargo claim'].map(t=>`<option ${state.type===t?'selected':''}>${t}</option>`).join('')}</select></div>${field('title','ชื่อคดี *')}</div><div class="fields reference-fields">${field('ourRef','Our ref / TSB ref')}${field('customerRef','เลขอ้างอิงลูกค้า')}${field('policyRef','Policy ref / เลขอ้างอิงกรมธรรม์')}</div></section><section class="form-section focus-current" aria-labelledby="create-people-heading"><div class="section-head"><div><h2 id="create-people-heading">ผู้มอบหมายและลูกความ</h2><p>ระบุผู้ติดต่อ และใช้ข้อมูลร่วมกันได้เมื่อเป็นรายเดียวกัน</p></div></div>${peopleForm()}</section><section class="form-section focus-current" aria-labelledby="create-team-heading"><div class="section-head"><div><h2 id="create-team-heading">ผู้รับผิดชอบและทีม</h2><p>กำหนดเจ้าของคดี เพื่อให้ทีมเริ่มงานต่อได้</p></div></div>${selectField('lawyer','ทนายผู้รับผิดชอบหลัก',['อรณิชา วัฒนกุล','ธนกร เจริญกิจ','ณัฐชา ศิริกุล'])}<div class="always-open-team">${assistantForm()}${selectField('playbook','Playbook / ชุดงาน',['ยังไม่เลือก','Corporate · v1','Criminal · v1','คดีทางการแพทย์ · v1',...(isCargo()?['Cargo checklist · ตัวอย่างจาก Excel']:[])])}</div></section><footer class="form-footer"><span class="helper">เปิดคดีแล้วจึงเพิ่มเอกสาร รายละเอียด และมอบหมายงาน</span><div class="row"><button type="button" class="link" onclick="setPage('detail')">ยกเลิก</button><button class="btn primary" type="submit">เปิดคดี ${icon('arrow')}</button></div></footer></form></div>`};
nextCreate=function(){if(!state.title.trim()){toast('กรุณาระบุชื่อคดี');document.getElementById('rich-title')?.focus();return}state.stage='รับเรื่อง';state.caseStatus='คดีใหม่';setPage('detail');toast('เปิดแฟ้มตัวอย่างแล้ว · เพิ่มเอกสารและมอบหมายงานต่อได้')};
showReview=function(){genericDialog('ข้อมูลเปิดคดี',viewValues([['ชื่อคดี',state.title],['ประเภท',state.type],['เลขอ้างอิงลูกค้า',state.customerRef],['Our ref / TSB ref',state.ourRef],['Policy ref',state.policyRef],['ผู้มอบหมาย',state.customer],['ผู้ติดต่อ',state.contact],['ลูกความ',state.client],['ทนายหลัก',state.lawyer],['ผู้ช่วย',buddies.join(', ')],...extraCustomers.map((r,i)=>['ผู้มอบหมาย '+(i+2),r.name]),...extraClients.map((r,i)=>['ลูกความ '+(i+2),r.name])]))};
const fullDataBeforeFast=allCaseData;
allCaseData=function(){return fullDataBeforeFast()+fold('เลขอ้างอิงคดี',field('ourRef','Our ref / TSB ref')+field('policyRef','Policy ref / เลขอ้างอิงกรมธรรม์'))+fold('ศาลและหมายเลขคดี',courtForm())+fold('รายละเอียดและฟิลด์ตามประเภทคดี',field('description','รายละเอียดคดี','textarea')+customForm())};
const docsBeforeFast=docsHtml,checklistBeforeFast=checklistPanel,panelBeforeFast=panel;
function conditionalCargo(html){if(isCargo())return html;const t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('Cargo'))b.remove()});return t.innerHTML}
docsHtml=function(){return conditionalCargo(docsBeforeFast())};checklistPanel=function(){return conditionalCargo(checklistBeforeFast())};
panel=function(){if(activeTab==='ภาพรวม')return `<div class="block-title"><h2>งานของทีมในคดีนี้</h2><button class="link" onclick="setSecondary('ข้อมูลคดี')">ข้อมูลคดีทั้งหมด ↗</button></div>${baseTasks()}${isCargo()?'<div class="rich-notes"><div class="row between"><h3>Cargo claim</h3><button class="link" onclick="activeTab=\'Cargo claim\';render()">เปิดพื้นที่พิจารณา ↗</button></div><p class="muted small">ข้อมูลเคลม · ประเด็นพิจารณา 12 แถว · เอกสาร 16 รายการ</p></div>':''}${baseDocs()}${activity()}`;if(activeTab==='Cargo claim'&&!isCargo())activeTab='เอกสาร';return panelBeforeFast()};
activity=function(){return `<section style="margin-top:25px"><div class="block-title"><h2>ความเคลื่อนไหวคดี</h2><button class="link" onclick="newActivity()">+ เพิ่มกิจกรรม</button></div><div class="timeline"><div class="event">เปิดแฟ้มคดีตัวอย่าง<small>ยังไม่ได้ยื่นฟ้อง</small></div>${appointments.map(a=>`<div class="event">${esc(a.title)}<small>${esc(a.date)} · ${esc(a.description||'')}</small></div>`).join('')}</div></section>`};
detailPage=function(){const visibleTabs=mainTabs.filter(t=>t!=='Cargo claim'||isCargo());return `<div class="detail-heading"><div><div class="row"><span class="eyebrow" style="margin:0">MATTER · ตัวอย่าง 2569 / 0042</span><span class="pill">${esc(state.stage)}</span></div><h1>${esc(state.title||'แฟ้มคดีตัวอย่าง')}</h1><div class="case-meta"><span>${esc(state.client)}</span><span>· ${esc(state.type)}</span></div></div><button class="btn" onclick="manageCase()">${icon('settings')}<span>จัดการคดี</span></button></div><div class="core-strip"><span>Our ref / TSB ref <b>${esc(state.ourRef||'ยังไม่ระบุ')}</b></span><span>เลขอ้างอิงลูกค้า <b>${esc(state.customerRef||'ยังไม่ระบุ')}</b></span><span>Policy ref <b>${esc(state.policyRef||'ยังไม่ระบุ')}</b></span><span>ผู้รับผิดชอบ <b>${state.lawyer}</b></span><span>อายุความ <b>${esc(state.timeBarConfirmed||state.limitationDeadline||'ยังไม่ได้ยืนยัน')}</b></span></div><section class="next-action"><div><div class="eyebrow">งานสำคัญถัดไป</div><h2>มอบหมายงานให้ทีมเริ่มดำเนินการ</h2><p>กำหนดผู้รับผิดชอบ วันส่ง และสิ่งที่ต้องส่งให้ตรวจ</p></div><button class="btn" onclick="activeTab='งาน';render()">เปิดแผนงานของทีม ${icon('arrow')}</button></section><div class="detail-layout"><nav class="tabs" aria-label="ส่วนของคดี">${visibleTabs.map(t=>`<button class="tab ${t===activeTab?'active':''}" onclick="activeTab='${t}';render()">${t}</button>`).join('')}<select class="secondary-menu" aria-label="ส่วนงานอื่นของคดี" onchange="setSecondary(this.value)"><option disabled ${activeTab!=='ส่วนอื่น'?'selected':''}>ข้อมูลและส่วนงานอื่น</option>${['ข้อมูลคดี','คู่ความ','ประกันภัย','Notice / ก่อนฟ้อง','ข้อเท็จจริงและฎีกา','รายงานปิดงาน','บันทึกและการติดต่อ','เช็กลิสต์ / Playbook'].map(t=>`<option ${activeTab==='ส่วนอื่น'&&secondary===t?'selected':''}>${t}</option>`).join('')}</select></nav><div class="detail-grid ${activeTab!=='ภาพรวม'?'wide-panel':''}"><main class="work-main">${panel()}</main>${fullFileMeta()}</div></div>`};
css.textContent+=`.fast-create .form-section{display:block!important}.fast-create .summary-side{display:block!important}body[data-variant=C] .fast-create{grid-template-columns:minmax(0,1fr) 275px}body[data-variant=C] .fast-create .paper{grid-column:1;grid-row:1;background:white;border:1px solid var(--line)}body[data-variant=C] .fast-create .form-section{padding:25px 28px}body[data-variant=C] .fast-create .summary-side{grid-column:2;grid-row:1;border:0;padding-top:4px}body[data-variant=C] .fast-create .summary-side h2{display:block}@media(max-width:800px){.fast-create .summary-side{display:none!important}.fast-create .form-section{padding:22px 19px!important}}`;
// White workspace: section hierarchy comes from headings, borders and spacing.
css.textContent+=`
:root{--bg:#fff;--line:#e5e8ed}
body,.shell,.workspace,.topbar{background:#fff}
.fast-create .paper{border-radius:8px;box-shadow:none}
.fast-create .section-head{margin-bottom:20px}
.fast-create .section-head h2{font-size:16px}
.fast-create .section-num{color:#8692a3}
.fast-create .form-section{background:#fff;padding:26px 28px}
.fast-create .form-section+.form-section{border-top:0}
.fast-create .form-footer{background:#fff}
.fast-create .summary-side{padding:8px 0 8px 22px;border-left:1px solid var(--line)}
body[data-variant=B] .fast-create .summary-side{margin-top:24px}
body[data-variant=C] .fast-create .summary-side{padding:8px 0 8px 22px;border-left:1px solid var(--line)}
body .next-action,body[data-variant=B] .next-action,body[data-variant=C] .next-action{background:#fff;border:1px solid var(--line);border-left:3px solid var(--blue);box-shadow:none}
.work-main>.tasks,.work-main>.rich-notes{padding-bottom:24px;border-bottom:1px solid var(--line)}
.data-table th{background:#fafbfc}
.source-hint{background:#fff;border:1px solid var(--line);border-left:2px solid #b9c7dc}
@media(max-width:800px){.fast-create .section-head{gap:10px}.fast-create .section-head p{font-size:11px}.fast-create .form-footer{flex-wrap:wrap}}
`;

css.textContent+=`
.client-record>.fields{grid-template-columns:minmax(0,1fr)}
.record-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}
.record-heading h3{order:-1}
.record-row .record-heading>.remove{float:none;flex-shrink:0}
.primary-client-fields{display:grid;gap:14px;margin-top:14px}
.primary-client-fields>.quiet-check{margin:0}
.client-record{padding:20px 0}
`;

css.textContent+=`.always-open-team{margin-top:22px;padding-top:20px;border-top:1px solid var(--line)}.always-open-team>.field{margin-top:20px}`;

render();
